	private static void runBenchmarkLifecycle(String mode) throws Exception {
		Path root = requiredPath("rdf4j.q12.postAliasRoot");
		Path output = root.resolve(mode);
		Path storeRoot = root.resolve("stores/" + mode + "-store");
		Path manifest = output.resolve("lifecycle.manifest");
		Path queryFile = requiredPath("rdf4j.q12.query");
		assertFalse(Files.exists(manifest), "do not overwrite the " + mode + " lifecycle manifest");
		Files.createDirectories(output);
		System.setProperty("rdf4j.q12.mode", mode);
		System.setProperty("rdf4j.q12.storeRoot", storeRoot.toString());
		System.setProperty("rdf4j.q12.manifest", manifest.toString());
		System.setProperty("rdf4j.q12.query", queryFile.toString());
		System.setProperty("rdf4j.test.outputDirectory", output.resolve("test-output").toString());
		setBenchmarkProperties();
		new ThemeQueryFullLifecycleProbeTest().runFullThemeQueryLifecycle();
	}

	private static void setBenchmarkProperties() {
		System.setProperty("rdf4j.benchmark.profiling", "true");
		System.setProperty(ThemeQueryBenchmark.WAIT_FOR_SKETCHES_PROPERTY, "false");
		System.setProperty(ThemeQueryBenchmark.WAIT_FOR_DIRECT_ADJACENCY_PROPERTY, "true");
		System.setProperty(ThemeQueryBenchmark.WAIT_FOR_VALUE_OVERLAY_PROPERTY, "true");
		System.setProperty("rdf4j.lmdb.valueOverlay.maxBytes", "4294967296");
		System.setProperty("rdf4j.lmdb.valueOverlay.retained.maxBytes", "2147483648");
		System.setProperty("rdf4j.lmdb.valueOverlay.reverseSlots", "65536");
	}

	private static String canonicalRow(BindingSet row) {
		StringBuilder result = new StringBuilder();
		boolean first = true;
		for (String name : new TreeSet<>(row.getBindingNames())) {
			if (!first) {
				result.append('\t');
			}
			first = false;
			result.append(base64(name)).append('=').append(canonicalValue(row.getValue(name)));
		}
		return result.toString();
	}

	private static String canonicalValue(Value value) {
		if (value == null) {
			return "NULL";
		}
		if (value instanceof org.eclipse.rdf4j.model.IRI iri) {
			return "I:" + base64(iri.stringValue());
		}
		if (value instanceof BNode blankNode) {
			return "B:" + base64(blankNode.getID());
		}
		if (value instanceof Literal literal) {
			String language = literal.getLanguage().orElse("");
			return "L:" + base64(literal.getLabel()) + ':' + base64(literal.getDatatype().stringValue()) + ':'
					+ base64(language);
		}
		if (value instanceof TripleTerm triple) {
			return "T:" + canonicalValue(triple.getSubject()) + ':' + canonicalValue(triple.getPredicate()) + ':'
					+ canonicalValue(triple.getObject());
		}
		return "V:" + base64(value.getClass().getName()) + ':' + base64(value.stringValue());
	}

	private static String base64(String value) {
		return Base64.getUrlEncoder().withoutPadding().encodeToString(value.getBytes(StandardCharsets.UTF_8));
	}

	private static Path requiredPath(String property) {
		String value = System.getProperty(property);
		assertTrue(value != null && !value.isBlank(), "missing system property: " + property);
		return Path.of(value).toAbsolutePath().normalize();
	}

	private static String sha256(Path path) throws Exception {
		try (var input = Files.newInputStream(path)) {
			var digest = java.security.MessageDigest.getInstance("SHA-256");
			byte[] buffer = new byte[64 * 1024];
			int count;
			while ((count = input.read(buffer)) >= 0) {
				digest.update(buffer, 0, count);
			}
			return java.util.HexFormat.of().formatHex(digest.digest());
		}
	}

	private static String sha256(byte[] bytes) throws Exception {
		return java.util.HexFormat.of()
				.formatHex(
						java.security.MessageDigest.getInstance("SHA-256").digest(bytes));
	}
